from typing import List, Sequence, Tuple

def select_lots_fefo(lots: Sequence[Tuple[str, int, int]], qty: int, today: int, min_shelf_days: int = 0) -> List[Tuple[str, int]]:
    if qty < 0:
        raise ValueError("qty must be non-negative")
    eligible = []
    for lid, exp, av in lots:
        if exp > today and (exp - today) >= min_shelf_days:
            eligible.append((lid, exp, av))
    eligible.sort(key=lambda x: (x[1], x[0]))
    if sum(l[2] for l in eligible) < qty:
        raise ValueError("Not enough stock")
    res = []
    rem = qty
    for lid, _, av in eligible:
        if rem <= 0: break
        take = min(rem, av)
        if take > 0:
            res.append((lid, take))
            rem -= take
